e=[{question:"BCS ও প্রাথমিক শিক্ষক পরীক্ষার সিলেবাসের কতটুকু মিল আছে?",answer:"দুটি পরীক্ষার সিলেবাসের প্রায় ৬০% অংশ একই — বাংলা ব্যাকরণ, ইংরেজি Grammar, পাটিগণিত এবং বাংলাদেশ বিষয়াবলী উভয়েই গুরুত্বপূর্ণ। মূল পার্থক্য হলো BCS-এ অতিরিক্ত ইংরেজি সাহিত্য (১৫ নম্বর), মানসিক দক্ষতা (১৫ নম্বর), কম্পিউটার (১৫ নম্বর) ও নৈতিকতা (১০ নম্বর) আলাদাভাবে পড়তে হয়।"},{question:"BCS নাকি প্রাথমিক — নতুন প্রার্থীর কোনটা দিয়ে শুরু করা উচিত?",answer:"নতুন প্রার্থীদের জন্য পরামর্শ হলো প্রথমে প্রাথমিক শিক্ষক পরীক্ষার প্রস্তুতি নিন। কারণ সিলেবাস সহজ, ৩–৪ মাসে ভালো প্রস্তুতি সম্ভব এবং এই প্রস্তুতিতেই BCS-এর ৬০% সিলেবাস শেষ হয়ে যাবে। প্রাথমিক পাস করলে চাকরি নিশ্চিত করে BCS-এর আরও গভীর প্রস্তুতি নেওয়া যাবে।"},{question:"BCS ও প্রাথমিক পরীক্ষা একসাথে দেওয়া কি সম্ভব?",answer:"হ্যাঁ, সম্ভব এবং কার্যকর। প্রতি সপ্তাহে ৩ দিন shared বিষয় (বাংলা, ইংরেজি Grammar, গণিত, বাংলাদেশ বিষয়াবলী) এবং ২ দিন BCS-only বিষয় (ইংরেজি সাহিত্য, মানসিক দক্ষতা, কম্পিউটার) পড়লে দুটো পরীক্ষার জন্যই ভালো প্রস্তুতি হবে।"},{question:"প্রাথমিক শিক্ষক ও BCS-এর নেগেটিভ মার্কিং-এ পার্থক্য কী?",answer:"প্রাথমিক শিক্ষক পরীক্ষায় প্রতি ভুলে ০.২৫ নম্বর কাটা যায়, আর BCS প্রিলিমিনারিতে প্রতি ভুলে ০.৫০ নম্বর কাটা যায় — অর্থাৎ BCS-এ নেগেটিভ মার্কিং দ্বিগুণ। তাই BCS-এ অনিশ্চিত প্রশ্নে উত্তর দেওয়া আরও বেশি ঝুঁকিপূর্ণ।"},{question:"প্রাথমিক পরীক্ষায় পাস করার হার কত?",answer:"৯ জানুয়ারি ২০২৬ তারিখের পরীক্ষায় ১০,৮০,০৮০ জন অংশগ্রহণ করেন এবং ১৪,৩৮৪ জন উত্তীর্ণ হন — পাসের হার মাত্র ১.৩৩%। BCS প্রিলিমিনারিতে সাধারণত ৫–১০% উত্তীর্ণ হন। উভয় পরীক্ষায় প্রতিযোগিতা তীব্র, তাই পরিকল্পিত প্রস্তুতি অপরিহার্য।"}],pe=[{label:"একনজরে তুলনা",anchorId:"quick-comparison"},{label:"সিলেবাস — মিল ও পার্থক্য",anchorId:"syllabus-comparison"},{label:"একসাথে প্রস্তুতি কি সম্ভব?",anchorId:"together-preparation"},{label:"৬ মাসের সমন্বিত রুটিন",anchorId:"combined-routine"},{label:"বিষয়ভিত্তিক রিসোর্স",anchorId:"subject-resources"},{label:"চাকরির সুবিধা তুলনা",anchorId:"job-benefits"},{label:"চূড়ান্ত পরামর্শ",anchorId:"final-recommendation"}];func